def minEditsToSubstring(text, pattern):
    m = len(pattern)
    col = list(range(m + 1))
    best = col[m]
    for ch in text:
        new = [0] * (m + 1)
        for i in range(1, m + 1):
            if pattern[i - 1] == ch:
                x = col[i - 1]
            else:
                x = col[i - 1] + 1
            y = col[i] + 1
            if y < x:
                x = y
            y = new[i - 1] + 1
            if y < x:
                x = y
            new[i] = x
        col = new
        if col[m] < best:
            best = col[m]
    return best
